export type BalanceTransaction = { /** Signed gross amount of this balance movement, before any fee. */ "amount_money": { /** Signed amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** RFC3339 timestamp. Format: date-time. */ "available_at"?: string; "balance_transaction_id": string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; "description"?: string; /** Flint fee for this balance movement, never a provider cost passed through. Charges are positive; returned fees are negative. A payment of 5000 with a fee of 175 has a net amount of 4825. A payout reversal returning a fee of 25 reports fee_money -25. */ "fee_money": { /** Signed amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "hold_detail"?: { "held_money"?: MoneyValue; "released_money"?: MoneyValue; "used_money"?: MoneyValue; }; "merchant_id": string; /** Signed net effect on your Flint balance: amount_money minus fee_money in the same currency. */ "net_money": { /** Signed amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** RFC3339 timestamp. Format: date-time. */ "occurred_at": string; "order"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed" | (string & {}); "order_id": string; "order_number"?: string; "payment_intent_ids"?: Array<string>; "payment_status": "unpaid" | "partially_paid" | "paid" | (string & {}); "pricing_amounts": PricingAmounts; "refund_status": "none" | "partially_refunded" | "refunded" | (string & {}); "settlement_amounts": SettlementAmounts; "status": "open" | "closed" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "order_id"?: string; /** Flint payout containing this balance transaction. Present after the paid payout's entries are recorded. */ "payout_id"?: string; "related_balance_transaction_ids"?: Array<string>; "related_resource"?: ({  }) & (({ "payment_intent_id": string; "type": "payment_intent"; }) | ({ "refund_id": string; "type": "refund"; }) | ({ "dispute_id": string; "type": "dispute"; }) | ({ "payout_id": string; "type": "payout"; }) | ({ "payout_destination_id": string; "type": "payout_destination"; }) | ({ "merchant_subscription_invoice_id": string; "type": "merchant_subscription_invoice"; }) | (object)); "status": "pending" | "available" | "reserved" | "reversed" | "failed" | "superseded" | (string & {}); "type": "payment" | "refund" | "dispute" | "dispute_reversal" | "return" | "recovery" | "payout" | "payout_failure" | "payout_cancellation" | "payout_reversal" | "payout_advance" | "payout_advance_funding" | "reserve_hold" | "reserve_release" | "payout_hold" | "payout_hold_release" | "adjustment" | "merchant_billing_payment" | "merchant_billing_payment_reversal" | (string & {}); };
